package com.example.sgva.domain

/**
 * Puerto de salida (Outbound/Driven Port) para persistir y recuperar las
 * entidades de dominio ya validadas (`DESIGN_SGVA.md` §3).
 *
 * El dominio declara la interfaz; la tecnología concreta vive en
 * `infrastructure` y nunca al revés (Inversión de Dependencia). En esta versión
 * el único adaptador es en memoria; un futuro adaptador Spring Data debe poder
 * sustituirlo sin tocar el dominio ni los casos de uso.
 *
 * Toda entidad que entra o sale de este puerto es válida por construcción: sus
 * invariantes se verifican en el bloque `init` de [Estudiante] y [Docente], no
 * aquí ni en los adaptadores (`DESIGN_SGVA.md` §0.1).
 *
 * El identificador (`id`) es la clave de identidad de cada entidad. Este puerto
 * solo almacena y consulta; la regla de aplicación "un `id` no puede
 * registrarse dos veces" la aplican los casos de uso de registro.
 */
interface AcademicDataRepository {

    /** Persiste [estudiante] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarEstudiante(estudiante: Estudiante): Estudiante

    /** Devuelve el estudiante con [id], o `null` si no hay ninguno registrado. */
    fun buscarEstudiantePorId(id: String): Estudiante?

    /** Devuelve todos los estudiantes registrados, en orden de inserción. */
    fun listarEstudiantes(): List<Estudiante>

    /** Persiste [docente] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarDocente(docente: Docente): Docente

    /** Devuelve el docente con [id], o `null` si no hay ninguno registrado. */
    fun buscarDocentePorId(id: String): Docente?

    /** Devuelve todos los docentes registrados, en orden de inserción. */
    fun listarDocentes(): List<Docente>

    /** Persiste [respuesta] indexada por su `id` y la devuelve sin cambios. */
    fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta

    /** Devuelve la respuesta de encuesta con [id], o `null` si no hay ninguna registrada. */
    fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta?

    /** Devuelve todas las respuestas de encuesta registradas, en orden de inserción. */
    fun listarRespuestasEncuesta(): List<RespuestaEncuesta>

    /** Persiste [resultado] y lo devuelve sin cambios. */
    fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta

    /**
     * Devuelve el resultado de encuesta por pregunta cuya clave natural es
     * ([programa], [periodo], [codigoPregunta]), o `null` si no hay ninguno registrado.
     */
    fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta?

    /** Devuelve todos los resultados de encuesta por pregunta registrados, en orden de inserción. */
    fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta>

    /** Persiste [evaluacion] y la devuelve sin cambios. */
    fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental

    /**
     * Devuelve la evaluación documental cuya clave natural es ([programa],
     * [periodo], [caracteristica]), o `null` si no hay ninguna registrada.
     */
    fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental?

    /** Devuelve todas las evaluaciones documentales registradas, en orden de inserción. */
    fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental>
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.ResultadoEncuestaPregunta

/**
 * Consulta los resultados de encuesta por pregunta registrados (Módulo 4): el
 * listado completo o uno concreto por su clave natural (programa, periodo,
 * código de pregunta). No modifica el estado del repositorio.
 */
class ConsultarResultadoEncuestaPreguntaUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /** Devuelve todos los resultados registrados, en orden de inserción. */
    fun listarTodos(): List<ResultadoEncuestaPregunta> = repositorio.listarResultadosEncuestaPregunta()

    /**
     * Devuelve el resultado cuya clave natural es ([programa], [periodo],
     * [codigoPregunta]), o `null` si no existe ninguno con esa clave.
     */
    fun buscarPorClave(programa: String, periodo: String, codigoPregunta: String): ResultadoEncuestaPregunta? =
        repositorio.buscarResultadoEncuestaPregunta(programa, periodo, codigoPregunta)
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.PonderacionLikert

/**
 * Módulo 3 — ponderación Likert de las encuestas de percepción
 * (`DESIGN_SGVA.md` §2).
 *
 * Promedia la `calificacion` de las respuestas registradas agrupándolas por
 * `factor` y `estamento`, opcionalmente restringidas a un periodo. Las
 * respuestas de encuesta no tienen `facultad` (Sección 0 de `DESIGN_SGVA.md`);
 * a diferencia de [CalculoDeIndicadorUseCase], este caso de uso no ofrece ese
 * filtro.
 */
class CalcularPonderacionLikertUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * @throws DatosInsuficientesException si no hay respuestas registradas para el filtro dado.
     */
    fun ejecutar(periodo: String? = null): List<PonderacionLikert> {
        val filtroPeriodo = periodo?.trim()?.takeIf { it.isNotEmpty() }
        val respuestas = repositorio.listarRespuestasEncuesta()
            .filter { filtroPeriodo == null || it.periodo == filtroPeriodo }

        if (respuestas.isEmpty()) {
            throw DatosInsuficientesException(
                "No hay respuestas de encuesta registradas para calcular la ponderación Likert" +
                    (filtroPeriodo?.let { " (periodo '$it')" } ?: "") + ".",
            )
        }

        val etiquetaPeriodo = filtroPeriodo ?: IndicadorCalidad.CONSOLIDADO

        return respuestas
            .groupBy { it.factor to it.estamento }
            .toSortedMap(compareBy({ it.first }, { it.second }))
            .map { (clave, grupo) ->
                PonderacionLikert(
                    factor = clave.first,
                    estamento = clave.second,
                    promedio = redondearACentesimas(grupo.map { it.calificacion }.average()),
                    periodo = etiquetaPeriodo,
                )
            }
    }

    private fun redondearACentesimas(valor: Double): Double = Math.round(valor * 100.0) / 100.0
}

package com.example.sgva.domain

/**
 * Reglas de formato compartidas por las entidades del dominio. Centraliza la
 * verificación del formato `AAAAS` para que `Estudiante.cohorte` y
 * `Docente.periodo` apliquen exactamente el mismo criterio.
 */
internal object ReglasDeFormato {

    /** Regex de referencia definida en `DESIGN_SGVA.md`, Sección 0.1. */
    private val PATRON_PERIODO_ACADEMICO = Regex("""^\d{4}[12]$""")

    /**
     * Verifica que [valor] cumpla el formato `AAAAS` y lo devuelve sin cambios.
     *
     * @throws FormatoPeriodoInvalidoException si el formato no es válido.
     */
    fun exigirPeriodoAcademico(valor: String, campo: String): String {
        if (!PATRON_PERIODO_ACADEMICO.matches(valor)) {
            throw FormatoPeriodoInvalidoException(campo, valor)
        }
        return valor
    }

    /**
     * Verifica que [valor] no esté vacío ni en blanco y lo devuelve sin cambios.
     *
     * @throws CampoRequeridoVacioException si el valor está en blanco.
     */
    fun exigirNoVacio(valor: String, campo: String): String {
        if (valor.isBlank()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /**
     * Verifica que [valor] contenga al menos un elemento y lo devuelve sin
     * cambios. Aplica a los conjuntos obligatorios de la entidad (ej.
     * `ResultadoEncuestaPregunta.estamentos`).
     *
     * @throws CampoRequeridoVacioException si el conjunto está vacío.
     */
    fun <T> exigirNoVacio(valor: Set<T>, campo: String): Set<T> {
        if (valor.isEmpty()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /** Tolerancia numérica para las sumas de ponderaciones (`DESIGN_SGVA.md` §0.1). */
    const val TOLERANCIA_SUMA_PONDERACIONES: Double = 0.001

    /**
     * Verifica que [valor] no sea negativo y lo devuelve sin cambios. Aplica a
     * todo peso del modelo de ponderaciones (factores, características y
     * mezcla encuestas/documental; `DESIGN_SGVA.md` §0.1).
     *
     * @throws PonderacionNegativaException si [valor] es negativo.
     */
    fun exigirPonderacionNoNegativa(valor: Double, contexto: String): Double {
        if (valor < 0.0) {
            throw PonderacionNegativaException(contexto, valor)
        }
        return valor
    }

    /**
     * Verifica que [suma] sea igual a `1.0` dentro de
     * [TOLERANCIA_SUMA_PONDERACIONES] y la devuelve sin cambios.
     *
     * @throws SumaPonderacionesInvalidaException si [suma] se aleja de `1.0` más que la tolerancia.
     */
    fun exigirSumaUno(suma: Double, contexto: String): Double {
        if (kotlin.math.abs(suma - 1.0) > TOLERANCIA_SUMA_PONDERACIONES) {
            throw SumaPonderacionesInvalidaException(contexto, suma)
        }
        return suma
    }
}

package com.example.sgva.application

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Doble de prueba en memoria del puerto [AcademicDataRepository]. Permite
 * ejercitar los casos de uso sin depender del adaptador de infraestructura.
 * Pública (no `internal`) para poder exponerse como bean de Spring en las
 * pruebas de integración de `infrastructure.web` (`ConfiguracionCasosDeUsoDePrueba`).
 */
class RepositorioAcademicoFalso : AcademicDataRepository {

    private val estudiantes = LinkedHashMap<String, Estudiante>()
    private val docentes = LinkedHashMap<String, Docente>()
    private val respuestasEncuesta = LinkedHashMap<String, RespuestaEncuesta>()
    private val resultadosEncuestaPregunta = LinkedHashMap<String, ResultadoEncuestaPregunta>()
    private val evaluacionesDocumentales = LinkedHashMap<String, EvaluacionDocumental>()

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantes[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantes[id]

    override fun listarEstudiantes(): List<Estudiante> = estudiantes.values.toList()

    override fun guardarDocente(docente: Docente): Docente {
        docentes[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentes[id]

    override fun listarDocentes(): List<Docente> = docentes.values.toList()

    override fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        respuestasEncuesta[respuesta.id] = respuesta
        return respuesta
    }

    override fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta? = respuestasEncuesta[id]

    override fun listarRespuestasEncuesta(): List<RespuestaEncuesta> = respuestasEncuesta.values.toList()

    override fun guardarResultadoEncuestaPregunta(resultado: ResultadoEncuestaPregunta): ResultadoEncuestaPregunta {
        resultadosEncuestaPregunta[claveDe(resultado.programa, resultado.periodo, resultado.codigoPregunta)] =
            resultado
        return resultado
    }

    override fun buscarResultadoEncuestaPregunta(
        programa: String,
        periodo: String,
        codigoPregunta: String,
    ): ResultadoEncuestaPregunta? = resultadosEncuestaPregunta[claveDe(programa, periodo, codigoPregunta)]

    override fun listarResultadosEncuestaPregunta(): List<ResultadoEncuestaPregunta> =
        resultadosEncuestaPregunta.values.toList()

    private fun claveDe(programa: String, periodo: String, codigoPregunta: String): String =
        "$programa|$periodo|$codigoPregunta"

    override fun guardarEvaluacionDocumental(evaluacion: EvaluacionDocumental): EvaluacionDocumental {
        evaluacionesDocumentales[claveDe(evaluacion.programa, evaluacion.periodo, evaluacion.caracteristica)] =
            evaluacion
        return evaluacion
    }

    override fun buscarEvaluacionDocumental(
        programa: String,
        periodo: String,
        caracteristica: String,
    ): EvaluacionDocumental? = evaluacionesDocumentales[claveDe(programa, periodo, caracteristica)]

    override fun listarEvaluacionesDocumentales(): List<EvaluacionDocumental> =
        evaluacionesDocumentales.values.toList()

    /** Vacía los cinco almacenes; útil para reutilizar la misma instancia entre pruebas. */
    fun limpiar() {
        estudiantes.clear()
        docentes.clear()
        respuestasEncuesta.clear()
        resultadosEncuestaPregunta.clear()
        evaluacionesDocumentales.clear()
    }
}

package com.example.sgva.application

import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ValoracionCualitativa
import com.example.sgva.usecases.ConsultarEvaluacionDocumentalUseCase
import com.example.sgva.usecases.RegistrarEvaluacionDocumentalUseCase
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals
import kotlin.test.assertNull

class GestionEvaluacionesDocumentalesUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val registrar = RegistrarEvaluacionDocumentalUseCase(repositorio)
    private val consultar = ConsultarEvaluacionDocumentalUseCase(repositorio)

    @Test
    fun `registrar una evaluacion la hace recuperable por su clave natural`() {
        val evaluacion = evaluacion(caracteristica = "1.1")

        registrar.ejecutar(evaluacion)

        assertEquals(evaluacion, consultar.buscarPorClave("EGSTI", "20261", "1.1"))
    }

    @Test
    fun `el listado devuelve las evaluaciones en orden de registro`() {
        val primera = evaluacion(caracteristica = "1.1")
        val segunda = evaluacion(caracteristica = "1.2")

        registrar.ejecutar(primera)
        registrar.ejecutar(segunda)

        assertEquals(listOf(primera, segunda), consultar.listarTodas())
    }

    @Test
    fun `registrar una clave natural ya existente es rechazado sin sobrescribir el registro previo`() {
        val original = evaluacion(caracteristica = "1.1", calificacion = 4.5)
        registrar.ejecutar(original)

        assertThrows<EntidadDuplicadaException> {
            registrar.ejecutar(evaluacion(caracteristica = "1.1", calificacion = 2.0))
        }
        assertEquals(original, consultar.buscarPorClave("EGSTI", "20261", "1.1"))
    }

    @Test
    fun `dos evaluaciones del mismo periodo y programa con distinta caracteristica no son duplicadas`() {
        registrar.ejecutar(evaluacion(caracteristica = "1.1"))

        registrar.ejecutar(evaluacion(caracteristica = "1.2"))

        assertEquals(2, consultar.listarTodas().size)
    }

    @Test
    fun `consultar una clave inexistente devuelve null`() {
        assertNull(consultar.buscarPorClave("NO-EXISTE", "20261", "1.1"))
    }

    @Test
    fun `el listado esta vacio cuando no hay evaluaciones registradas`() {
        assertEquals(emptyList(), consultar.listarTodas())
    }

    @Test
    fun `la valoracion cualitativa de la evaluacion recuperada se deriva de su calificacion`() {
        registrar.ejecutar(evaluacion(caracteristica = "1.1", calificacion = 4.8))

        val recuperada = consultar.buscarPorClave("EGSTI", "20261", "1.1")

        assertEquals(ValoracionCualitativa.SE_CUMPLE_PLENAMENTE, recuperada?.valoracionCualitativa)
    }

    private fun evaluacion(
        caracteristica: String,
        calificacion: Double = 4.0,
    ): EvaluacionDocumental = EvaluacionDocumental(
        programa = "EGSTI",
        caracteristica = caracteristica,
        periodo = "20261",
        calificacion = calificacion,
    )
}

